from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    print("Testing SSE validation...")

    try:
        ServerSentEvent(event="line1\nline2")
        print("FAILED: ServerSentEvent(event='line1\\nline2') should have raised ValidationError")
    except ValidationError as e:
        print("PASSED: ServerSentEvent(event='line1\\nline2') raised ValidationError")
        print(e)

    try:
        ServerSentEvent(id="line1\nline2")
        print("FAILED: ServerSentEvent(id='line1\\nline2') should have raised ValidationError")
    except ValidationError as e:
        print("PASSED: ServerSentEvent(id='line1\\nline2') raised ValidationError")
        print(e)

    try:
        ServerSentEvent(id="line1\rline2")
        print("FAILED: ServerSentEvent(id='line1\\rline2') should have raised ValidationError")
    except ValidationError as e:
        print("PASSED: ServerSentEvent(id='line1\\rline2') raised ValidationError")
        print(e)

    try:
        ServerSentEvent(id="line1\0line2")
        print("PASSED: ServerSentEvent(id='line1\\0line2') raised ValidationError (existing behavior)")
    except ValidationError as e:
        print("PASSED: ServerSentEvent(id='line1\\0line2') raised ValidationError")

if __name__ == "__main__":
    test_sse_validation()

