from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_newlines():
    # Test event with newline
    try:
        ServerSentEvent(event="event\nname")
        print("Failed: event with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: event with newline raised ValidationError: {e}")

    # Test id with newline
    try:
        ServerSentEvent(id="id\n123")
        print("Failed: id with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: id with newline raised ValidationError: {e}")

    # Test id with null character (should still fail)
    try:
        ServerSentEvent(id="id\0123")
        print("Failed: id with null character should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: id with null character raised ValidationError: {e}")

    # Test valid event
    try:
        ServerSentEvent(event="valid_event", id="valid_id")
        print("Success: valid event and id passed")
    except ValidationError as e:
        print(f"Failed: valid event and id raised ValidationError: {e}")

if __name__ == "__main__":
    test_sse_newlines()

